ddl.example:
CREATE TABLE events (
  id         bigint NOT NULL PRIMARY KEY,
  tenant_id  integer NOT NULL,
  kind       varchar(40) NOT NULL,
  created_at timestamp with time zone NOT NULL
);

CREATE INDEX events_tenant_idx ON events (tenant_id);
CREATE INDEX events_tenant_kind_idx ON events (tenant_id, kind);
CREATE INDEX events_tenant_again_idx ON events (tenant_id);
CREATE INDEX events_id_idx ON events (id);
CREATE INDEX events_recent_idx ON events (created_at) WHERE created_at > now();
